// HTML Extraction using CSS selectors (Cheerio-like)
const input = $input.first().json;
const htmlContent = input.htmlContent;
const selectors = input.selectors;
const options = input.options || {};
const sourceUrl = input.sourceUrl;
const startTime = input.startTime;

// Simple HTML parser functions
function parseHTML(html) {
  return html;
}

// Clean whitespace
function cleanText(text) {
  if (!text) return '';
  if (options.clean_whitespace !== false) {
    return text.replace(/[\n\t\r]+/g, ' ').replace(/\s+/g, ' ').trim();
  }
  return text.trim();
}

// Extract text content from HTML element string
function extractText(html) {
  if (!html) return '';
  // Remove script and style content
  let text = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
  // Remove HTML tags
  text = text.replace(/<[^>]+>/g, ' ');
  // Decode HTML entities
  text = text.replace(/&nbsp;/g, ' ');
  text = text.replace(/&amp;/g, '&');
  text = text.replace(/&lt;/g, '<');
  text = text.replace(/&gt;/g, '>');
  text = text.replace(/&quot;/g, '"');
  text = text.replace(/&#39;/g, "'");
  return cleanText(text);
}

// Extract attribute from element
function extractAttribute(elementHtml, attrName) {
  if (!elementHtml || !attrName) return null;

  // Match attribute value
  const regex = new RegExp(`${attrName}\\s*=\\s*["']([^"']*)["']`, 'i');
  const match = elementHtml.match(regex);
  return match ? match[1] : null;
}

// Find elements by CSS selector (simplified)
function querySelectorAll(html, selector) {
  const results = [];

  // Parse selector
  let tagName = '*';
  let className = null;
  let idName = null;
  let attrMatch = null;

  // ID selector
  const idMatch = selector.match(/#([\w-]+)/);
  if (idMatch) idName = idMatch[1];

  // Class selector
  const classMatch = selector.match(/\.([\w-]+)/);
  if (classMatch) className = classMatch[1];

  // Tag selector
  const tagMatch = selector.match(/^([\w]+)/);
  if (tagMatch) tagName = tagMatch[1].toLowerCase();

  // Attribute selector [attr="value"]
  const attrSelectorMatch = selector.match(/\[([\w-]+)(?:=["']([^"']*)["'])?\]/);
  if (attrSelectorMatch) {
    attrMatch = { name: attrSelectorMatch[1], value: attrSelectorMatch[2] };
  }

  // Build regex to find matching elements
  let pattern;
  if (tagName !== '*') {
    pattern = new RegExp(`<${tagName}[^>]*>([\\s\\S]*?)<\/${tagName}>`, 'gi');
  } else {
    pattern = /<([a-z][a-z0-9]*)\b[^>]*>([\s\S]*?)<\/\1>/gi;
  }

  let match;
  while ((match = pattern.exec(html)) !== null) {
    const fullMatch = match[0];
    const openTag = fullMatch.match(/<[^>]+>/)?.[0] || '';

    let include = true;

    // Check ID
    if (idName) {
      const hasId = new RegExp(`id\\s*=\\s*["']${idName}["']`, 'i').test(openTag);
      if (!hasId) include = false;
    }

    // Check class
    if (className && include) {
      const classAttr = extractAttribute(openTag, 'class') || '';
      const classes = classAttr.split(/\s+/);
      if (!classes.includes(className)) include = false;
    }

    // Check attribute
    if (attrMatch && include) {
      const attrValue = extractAttribute(openTag, attrMatch.name);
      if (attrMatch.value !== undefined) {
        if (attrValue !== attrMatch.value) include = false;
      } else {
        if (attrValue === null) include = false;
      }
    }

    if (include) {
      results.push({
        html: fullMatch,
        openTag: openTag,
        text: extractText(fullMatch)
      });
    }
  }

  return results;
}

// Process each selector
const extractions = {};
let selectorsMatched = 0;
let selectorsFailed = 0;
const selectorErrors = [];

for (const sel of selectors) {
  const name = sel.name;
  const selector = sel.selector;
  const type = sel.type || 'css';
  const attribute = sel.attribute || 'text';
  const multiple = sel.multiple || false;

  try {
    let elements = [];

    if (type === 'css') {
      elements = querySelectorAll(htmlContent, selector);
    } else if (type === 'xpath') {
      // XPath support is limited in pure JS, use simplified approach
      // Extract tag name and basic conditions from xpath
      const xpathMatch = selector.match(/\/\/([\w]+)(?:\[@([\w-]+)(?:=["']([^"']*)["'])?\])?/);
      if (xpathMatch) {
        const tag = xpathMatch[1];
        const attr = xpathMatch[2];
        const attrVal = xpathMatch[3];
        let cssSelector = tag;
        if (attr && attrVal) {
          cssSelector = `${tag}[${attr}="${attrVal}"]`;
        } else if (attr) {
          cssSelector = `${tag}[${attr}]`;
        }
        elements = querySelectorAll(htmlContent, cssSelector);
      }
    }

    if (elements.length > 0) {
      selectorsMatched++;

      const extractValue = (el) => {
        if (attribute === 'text') {
          return el.text;
        } else if (attribute === 'html') {
          return el.html;
        } else {
          return extractAttribute(el.openTag, attribute);
        }
      };

      if (multiple) {
        extractions[name] = elements.map(el => {
          if (attribute === 'text') {
            return el.text;
          } else if (sel.attributes) {
            // Return multiple attributes as object
            const obj = { text: el.text };
            for (const attr of sel.attributes || ['href']) {
              obj[attr] = extractAttribute(el.openTag, attr);
            }
            return obj;
          } else {
            const value = extractValue(el);
            if (attribute !== 'text' && el.text) {
              return { text: el.text, [attribute]: value };
            }
            return value;
          }
        });
      } else {
        extractions[name] = extractValue(elements[0]);
      }
    } else {
      selectorsFailed++;
      selectorErrors.push({ name, selector, error: 'No elements found' });
      extractions[name] = multiple ? [] : null;
    }
  } catch (error) {
    selectorsFailed++;
    selectorErrors.push({ name, selector, error: error.message });
    extractions[name] = multiple ? [] : null;
  }
}

const response = {
  success: true,
  data: {
    extractions: extractions,
    source_url: sourceUrl,
    selectors_matched: selectorsMatched,
    selectors_failed: selectorsFailed
  },
  meta: {
    provider: 'cheerio-like',
    execution_mode: 'online',
    processing_time_ms: Date.now() - startTime
  }
};

if (selectorErrors.length > 0 && options.include_errors) {
  response.data.selector_errors = selectorErrors;
}

return { json: response };

